import React from 'react';

export default function Navbar({ activeTab, setActiveTab, userRole, currentUser, onOpenLogin, onLogout }) {
  // Only show Admin tabs if logged in as Admin.
  // For Passenger / Guest, home page is already Book Ride, so no redundant Book Ride tab in header!
  const tabs = userRole === 'admin' 
    ? [
        { id: 'booking', label: '🚖 Book Ride' },
        { id: 'orders', label: '📋 Orders & Trips' },
        { id: 'analytics', label: '📊 Analytics' },
        { id: 'drivers', label: '👨‍✈️ Drivers Fleet' },
        { id: 'customers', label: '👥 Customers' }
      ]
    : [];

  return (
    <header className="navbar">
      <div className="container nav-inner">
        <a href="#" className="brand-logo" onClick={(e) => { e.preventDefault(); setActiveTab('booking'); }}>
          <div className="logo-badge">🚖</div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span className="brand-name">DiyaTaxi</span>
              <span className="brand-tag">
                {userRole === 'admin' ? 'ADMIN' : 'PASSENGER'}
              </span>
            </div>
            <div style={{ fontSize: '11px', color: 'var(--text-muted)', letterSpacing: '0.2px' }}>
              {userRole === 'admin' ? 'Operations Control Center' : 'Urban Ride Hailing'}
            </div>
          </div>
        </a>

        {/* Navigation Tabs - only shown for Admin operations */}
        {tabs.length > 0 && (
          <ul className="nav-tabs" role="tablist">
            {tabs.map(tab => (
              <li key={tab.id}>
                <button
                  className={`nav-tab-btn ${activeTab === tab.id ? 'active' : ''}`}
                  onClick={() => setActiveTab(tab.id)}
                >
                  {tab.label}
                </button>
              </li>
            ))}
          </ul>
        )}

        {/* Right side auth & status */}
        <div className="nav-right-actions">
          {userRole === 'admin' ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <div style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                background: 'rgba(245, 158, 11, 0.12)',
                border: '1px solid rgba(245, 158, 11, 0.3)',
                padding: '6px 12px',
                borderRadius: '9999px',
                fontSize: '12px'
              }}>
                <span>🛡️</span>
                <span style={{ fontWeight: 700, color: 'var(--primary)' }}>
                  {currentUser?.name || 'Admin'}
                </span>
              </div>
              <button
                className="btn btn-secondary"
                style={{ padding: '6px 14px', fontSize: '12px' }}
                onClick={onLogout}
              >
                Logout 🚪
              </button>
            </div>
          ) : currentUser?.name ? (
            /* Logged in Passenger */
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <div style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                background: 'rgba(16, 185, 129, 0.12)',
                border: '1px solid rgba(16, 185, 129, 0.3)',
                padding: '6px 14px',
                borderRadius: '9999px',
                fontSize: '12px'
              }}>
                <span>👤</span>
                <span style={{ fontWeight: 700, color: 'var(--accent-emerald)' }}>
                  {currentUser.name}
                </span>
                <span style={{ fontSize: '10px', background: 'rgba(16, 185, 129, 0.25)', padding: '1px 6px', borderRadius: '4px', color: 'var(--accent-emerald)', fontWeight: 600 }}>
                  Passenger
                </span>
              </div>
              <button
                className="btn btn-secondary"
                style={{ padding: '6px 14px', fontSize: '12px' }}
                onClick={onLogout}
              >
                Logout 🚪
              </button>
              <button
                className="btn btn-primary"
                style={{ padding: '6px 14px', fontSize: '12px' }}
                onClick={() => onOpenLogin('admin')}
              >
                🔐 Admin
              </button>
            </div>
          ) : (
            /* Guest / Not logged in */
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <button
                className="btn btn-secondary"
                style={{ padding: '6px 14px', fontSize: '12px' }}
                onClick={() => onOpenLogin('customer')}
              >
                👤 Passenger Login
              </button>
              <button
                className="btn btn-primary"
                style={{ padding: '6px 14px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '6px' }}
                onClick={() => onOpenLogin('admin')}
              >
                <span>🔐 Admin Login</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}
